import {genomeReceipt} from './dawg-genome.js';
import {statsOf,baseTraits} from './dawg-career.js';
import {CATALOG,birthLook,lookOf,canWear,equipLook,shuffleLook,saveLook,lookRequirement,lookHash,flexRating,previewDawg,fashionReceipt} from './dawg-fashion.js';
import {ITEM_LEVELS} from './dawg-fashion-schema.js';
import {drawDawg} from './dawg-art.js';
import {DawgShowroom,drawSpriteAtlas} from './dawg-showroom.js';
const $=id=>document.getElementById(id);
const el=(tag,text)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;return n;};
function download(blob,name){const url=URL.createObjectURL(blob),a=el('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
export class DawgAtelier {
 constructor(io){this.io=io;this.id=null;this.draft=null;this.inputs=new Map();this.showroom=new DawgShowroom($('atelier3D'));this.showroom.onStatus=text=>$('atelierGraphicsStatus').textContent=text;
  $('atelierLighting').addEventListener('change',e=>this.showroom.setLighting(e.target.value));$('atelierQuality').addEventListener('change',e=>this.showroom.setQuality(e.target.value));
  $('exportDawgPhoto').onclick=()=>{this.showroom.draw();const canvas=this.showroom.gpu?.canvas||this.showroom.canvas;canvas.toBlob(blob=>{if(blob){download(blob,'DAWG-'+this.io.dawg().id.slice(0,8)+'-studio.png');this.io.notice('Studio photo saved with your current pose, view and lighting.');}},'image/png');};
  const change=e=>{const key=e.target.dataset.fashion;if(!key||!this.draft||e.type==='input'&&e.target.tagName==='SELECT')return;this.draft[key]=Number(e.target.value);this.paint();};$('wardrobeFields').addEventListener('change',change);$('wardrobeFields').addEventListener('input',change);
  $('equipFashion').onclick=()=>{if(!this.draft||!equipLook(this.io.dawg(),this.draft))return;this.io.save();this.io.notice('Look equipped. Your DNA and career stayed the same; all 2D games now use this fit.');};
  $('randomFashion').onclick=()=>{this.draft=shuffleLook(this.io.dawg());this.io.save();this.syncInputs();this.paint();this.io.notice('A SHA-256 style roll is ready to preview. Equip it to wear it.');};
  $('birthFashion').onclick=()=>{this.draft=birthLook(this.io.dawg());this.syncInputs();this.paint();this.io.notice('Birth look preview. Equip it to restore your original outfit and body styling.');};
  $('discardFashion').onclick=()=>{this.draft={...lookOf(this.io.dawg())};this.syncInputs();this.paint();this.io.notice('Preview reset to your equipped look.');};
  $('fashionPresets').addEventListener('click',e=>{const save=e.target.closest('[data-save-fit]'),wear=e.target.closest('[data-wear-fit]');const d=this.io.dawg();if(save){const slot=Number(save.dataset.saveFit),name=$('fitName'+slot).value?.trim();if(saveLook(d,slot,name,this.draft)){this.io.save();this.renderPresets();this.paint();this.io.notice('Saved '+name+'. Your outfit slot can be worn again anytime.');}else this.io.notice('Use a name of 1–24 characters and an unlocked outfit. Save slots in order.');}else if(wear){const saved=d.fashion?.looks[Number(wear.dataset.wearFit)];if(saved&&equipLook(d,saved.look)){this.draft={...saved.look};this.io.save();this.syncInputs();this.paint();this.io.notice('Wearing '+saved.name+'.');}}});
  $('atelierAnimation').addEventListener('change',e=>this.showroom.setAnimation(e.target.value));$('atelierRotate').onclick=()=>{this.showroom.auto=!this.showroom.auto;$('atelierRotate').setAttribute('aria-pressed',String(this.showroom.auto));this.showroom.loop();};$('atelierResetView').onclick=()=>this.showroom.reset();$('atelierZoom').addEventListener('input',e=>{this.showroom.zoom=Number(e.target.value);this.showroom.draw();});$('atelierViews').addEventListener('click',e=>{const b=e.target.closest('[data-view-yaw]');if(b){this.showroom.yaw=Number(b.dataset.viewYaw);this.showroom.draw();}});
  $('kennelDialog').addEventListener('close',()=>this.showroom.setVisible(false));
  $('exportDawgGLB').onclick=async()=>{if(!canWear(this.io.dawg(),this.draft))return;const preview=previewDawg(this.io.dawg(),this.draft);await this.exportBusy('exportDawgGLB',async()=>{const {exportModernGLB}=await import('./dawg-graphics-model.js');download(new Blob([await exportModernGLB(preview)],{type:'model/gltf-binary'}),'DAWG-'+preview.id.slice(0,8)+'-'+lookHash(preview).slice(0,8)+'.glb');this.io.notice('GLB saved: smooth meshes, PBR materials, a shared skeleton, weighted garments and Idle / Walk / Run clips.');});};
  $('exportDawgAtlas').onclick=()=>this.exportAtlas(false);
  $('exportDawgRunAtlas').onclick=()=>this.exportAtlas(true);
  $('exportDawgSeed').onclick=()=>{if(!canWear(this.io.dawg(),this.draft))return;const d=this.io.dawg(),receipt={format:'dawg-look-receipt',version:2,...fashionReceipt(d,this.draft),atlas:{frameWidth:256,frameHeight:320,columns:4,rows:2,yawDegrees:[0,45,90,135,180,225,270,315]},runAtlas:{frameWidth:256,frameHeight:320,columns:4,rows:3,frames:12,fps:25,view:'back'},asset:{format:'glTF 2.0 / GLB',units:'meters',up:'+Y',front:'+Z',graphicsVersion:2,animations:['Idle','Walk','Run'],rig:'shared skeleton; weighted torso, sleeves and trousers; rigid accessories'}};download(new Blob([JSON.stringify(receipt,null,2)],{type:'application/json'}),'DAWG-'+d.id.slice(0,8)+'-look-receipt.json');this.io.notice('Seed receipt downloaded. It describes this preview, including its look hash and 2D atlas layout.');};
 }
 async exportBusy(id,action){const button=$(id);button.disabled=true;try{await action();}catch(e){this.io.notice('Export could not complete. '+(e.message||'Try again in a moment.'));}finally{button.disabled=!canWear(this.io.dawg(),this.draft);}}
 async exportAtlas(run){if(!canWear(this.io.dawg(),this.draft))return;const preview=previewDawg(this.io.dawg(),this.draft);await this.exportBusy(run?'exportDawgRunAtlas':'exportDawgAtlas',async()=>{let canvas;if(typeof WebGL2RenderingContext!=='undefined'){try{const gpu=await import('./dawg-gpu.js');canvas=(await (run?gpu.createRunAtlas(preview,{width:256,height:320}):gpu.createTurntableAtlas(preview))).source;}catch{}}if(!canvas){if(run)throw Error('The 3D run atlas needs WebGL2. The turntable export is available in compatibility mode.');canvas=el('canvas');drawSpriteAtlas(canvas,preview);}await new Promise((resolve,reject)=>canvas.toBlob(blob=>{if(!blob){reject(Error('PNG encoding failed.'));return;}download(blob,'DAWG-'+preview.id.slice(0,8)+(run?'-run.png':'-turntable.png'));resolve();},'image/png'));this.io.notice(run?'Run atlas saved: 12 back-view frames, 4 × 3 grid, 256 × 320 pixels each.':'Turntable saved: 8 views, 4 × 2 grid, 256 × 320 pixels each.');});}
 open(){this.id=null;this.refresh();this.showroom.setVisible(true);}
 hide(){this.showroom.setVisible(false);}
 refresh(){const d=this.io.dawg();if(this.id!==d.id){this.id=d.id;this.draft={...lookOf(d)};this.buildInputs();}this.syncInputs();this.renderPresets();this.paint();}
 buildInputs(){const fields=[];this.inputs.clear();for(const [slot,{name,items}]of Object.entries(CATALOG)){const label=el('label'),title=el('span',name),select=el('select');select.dataset.fashion=slot;select.setAttribute('aria-label',name);items.forEach((name,i)=>{const need=ITEM_LEVELS[slot]?.[i]||0,option=el('option',name+(need?' · APPEARANCE '+need:''));option.value=String(i);select.append(option);});label.append(title,select);fields.push(label);this.inputs.set(slot,select);}for(const [slot,name]of [['hue','Outfit dye'],['accentHue','Accent dye'],['shoeHue','Footwear dye']]){const label=el('label'),title=el('span',name),range=el('input');range.type='range';range.min='0';range.max='359';range.step='1';range.dataset.fashion=slot;range.setAttribute('aria-label',name+' hue');label.append(title,range);fields.push(label);this.inputs.set(slot,range);}$('wardrobeFields').replaceChildren(...fields);}
 syncInputs(){for(const [key,input]of this.inputs)input.value=String(this.draft[key]);}
 paint(){if(!this.draft)return;const d=this.io.dawg(),preview=previewDawg(d,this.draft),appearance=statsOf(d).appearance,need=lookRequirement(this.draft),wear=canWear(d,this.draft);this.showroom.set(preview);const c=$('atelier2D').getContext('2d');c.clearRect(0,0,420,520);drawDawg(c,preview,210,260,470);$('atelierFlex').textContent=flexRating(preview)+' / 1000 FLEX';$('atelierAppearance').textContent='APPEARANCE '+appearance+' / 25';$('atelierLookHash').textContent='LOOK '+lookHash(d,this.draft).slice(0,16).toUpperCase();$('atelierSeedRoot').textContent=genomeReceipt(d).root;$('atelierGenome').textContent=d.genome?.version===2?'BIRTH GENOME · SHA-256 V2':'LEGACY GENOME · ORIGINAL LOOK PRESERVED';$('atelierLock').textContent=wear?'Ready to equip. Identity and game attributes stay permanent.':'Preview only · train Appearance to '+need+' to equip or export this look.';$('equipFashion').disabled=!wear;for(const id of ['exportDawgGLB','exportDawgAtlas','exportDawgRunAtlas','exportDawgPhoto','exportDawgSeed'])$(id).disabled=!wear;for(const [slot,input]of this.inputs)if(['hue','accentHue','shoeHue'].includes(slot))input.style.setProperty('--dye','hsl('+this.draft[slot]+' 65% 65%)');$('fashionProgress').textContent='Advanced drops at Appearance 5 / 10 / 15 / 20 / 25. Train Appearance in My kennel. Basic styles, body edits, and dyes are always free.';}
 renderPresets(){const d=this.io.dawg();$('fashionPresets').replaceChildren(...Array.from({length:3},(_,slot)=>{const saved=d.fashion?.looks[slot],card=el('div');card.className='fit-slot';const input=el('input');input.id='fitName'+slot;input.maxLength=24;input.value=saved?.name||['Street fit','After hours','Big flex'][slot];input.setAttribute('aria-label','Name for outfit slot '+(slot+1));const save=el('button',saved?'SAVE OVER SLOT '+(slot+1):'SAVE SLOT '+(slot+1));save.dataset.saveFit=String(slot);save.disabled=slot>(d.fashion?.looks.length||0);const wear=el('button','WEAR');wear.dataset.wearFit=String(slot);wear.disabled=!saved||!canWear(d,saved.look);card.append(el('small','LOOK '+String(slot+1).padStart(2,'0')),input,save,wear);return card;}));}
}
